#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  int dl;  char* text;  POINT pt;  COLORREF color;  } Queue_Text;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void ClearText(SQueue& q,void* s)  {  Queue_Text* p = (Queue_Text*)s;  delete [] p->text;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintText(DefinePaint)  {  QueueP(Queue_Text);  if ( p->color != 0xffffffff )    {    int nMode = ::SetBkMode(hDC,OPAQUE);    COLORREF old = ::SetBkColor( hDC, p->color );    ::TextOut(hDC,p->pt.x,p->pt.y,p->text,p->dl);    ::SetBkColor( hDC, old );    ::SetBkMode(hDC,nMode);    }  else  ::TextOut(hDC,p->pt.x,p->pt.y,p->text,p->dl);  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddText(DefineTegs)  {  AddQueueEx(Queue_Text);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintText;  p->clear = &ClearText;  p->color = 0xffffffff;  //  STegObj obj[] =    {    { 'P', "pt", &p->pt   },    { 'I', "x" , &p->pt.x },    { 'I', "y" , &p->pt.y },    { 'A', "color", &p->color  },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  p->dl = lstrlen(teg[0].value);  p->text = new char[p->dl+1];  lstrcpy( p->text, teg[0].value );  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddTextDbl   (DefineTegs)  {  AddQueueEx(Queue_Text);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintText;  p->clear = &ClearText;  p->color = 0xffffffff;  int nFloat = 0;  //  STegObj obj[] =    {    { 'P', "pt", &p->pt   },    { 'I', "x" , &p->pt.x },    { 'I', "y" , &p->pt.y },    { 'I', "float", &nFloat },    { 'A', "color", &p->color  },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  p->text = new char[32];  double dValue = Atof(teg[0].value);  char filtr[8] = "%.0f";  filtr[2] += nFloat;  sprintf_s( p->text, 32, filtr, dValue );  p->dl = lstrlen(p->text);  //  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddTextInt   (DefineTegs)  {  AddQueueEx(Queue_Text);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintText;  p->clear = &ClearText;  p->color = 0xffffffff;  //  STegObj obj[] =    {    { 'P', "pt", &p->pt   },    { 'I', "x" , &p->pt.x },    { 'I', "y" , &p->pt.y },    { 'A', "color", &p->color  },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  p->text = new char[32];  int nValue = Atoi(teg[0].value);  sprintf_s( p->text, 32, "%d", nValue );  p->dl = lstrlen(p->text);  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~